// Game creation is independent from event registration.
state.gameDraftMode=false;state.gameDraft=null;state.attachGameDraft=false;state.savedGameTemplates=[];
const autumnTemplate={id:'autumn-expo-wheel',type:'룰렛',en:'AUTUMN FAIR',title:'가을 박람회 룰렛',brand:'AUTUMN FAIR',headline:'가을의 행운을<br>돌려보세요.',desc:'가을 색상과 현장 참여 구성을 담은 박람회 룰렛',category:'현장 경품',useCases:['박람회','전시','현장'],seasons:['가을'],stage:'#ecd9ba',paper:'#fffaf0',ink:'#6c4932',accent:'#b56c3c',kind:'wheel'};
if(!gameTemplates.some(t=>t.id===autumnTemplate.id))gameTemplates.push(autumnTemplate);
for(const t of gameTemplates){t.useCases=t.useCases||[t.category,t.id==='lumiere-wheel'?'팝업스토어':t.id==='nova-scratch'?'박람회':'프로모션'];t.seasons=t.seasons||[]}
try{const saved=JSON.parse(localStorage.getItem('doitkit-game-templates')||'[]');if(Array.isArray(saved)){state.savedGameTemplates=saved.filter(t=>t.id&&t.kind&&t.draft);state.savedGameTemplates.forEach(t=>{if(!gameTemplates.some(x=>x.id===t.id))gameTemplates.push(t)})}}catch(e){}
function parseGamePrompt(p){const kind=/스크래치/.test(p)?'scratch':/퀴즈/.test(p)?'quiz':/메모리|카드/.test(p)?'memory':/슬롯/.test(p)?'slot':/반응|속도/.test(p)?'speed':'wheel';const countMatch=p.match(/(\d+)\s*개(?:의)?\s*(?:보기|항목|칸|선택지|경품)/);let count=countMatch?Math.max(2,Math.min(12,+countMatch[1])):0;const listMatch=p.match(/(?:선물|경품|보기|항목)(?:은|는|으로|:|：)\s*(.+?)(?=\s*(?:이|가)?\s*(?:있어|있었|있으면|있습니다|로 해|로 넣|로 구성|를 넣)|[.!?。]|$)/);let labels=listMatch?listMatch[1].split(/\s*[,，、/]\s*|\s+및\s+|\s+그리고\s+/).map(s=>s.trim().replace(/[‘’“”'"]/g,'')).filter(Boolean):[];if(labels.length===1&&!count)labels=[];if(!count)count=labels.length||6;if(!labels.length)labels=Array.from({length:count},(_,i)=>i===count-1?'꽝':`선물 ${i+1}`);while(labels.length<count)labels.push(`선물 ${labels.length+1}`);labels=labels.slice(0,count);return {prompt:p,kind,count,labels,season:/가을/.test(p)?'가을':/겨울/.test(p)?'겨울':/여름/.test(p)?'여름':/봄/.test(p)?'봄':'',useCase:/박람회/.test(p)?'박람회':/전시/.test(p)?'전시':/팝업/.test(p)?'팝업스토어':'',probabilityNote:'확률은 균등한 초안입니다. 운영 전에 수량과 지급 방식을 확인하세요.'}}
function recommendGameBases(spec){return gameTemplates.filter(t=>t.kind===spec.kind&&!t.draft).map(t=>{const reasons=[];let score=1;if(spec.season&&t.seasons.includes(spec.season)){score+=4;reasons.push(spec.season+' 테마')}if(spec.useCase&&t.useCases.some(u=>u.includes(spec.useCase))){score+=3;reasons.push(spec.useCase+' 구성')}if(!reasons.length)reasons.push(t.type+' 게임 유형');return {id:t.id,score,reasons}}).sort((a,b)=>b.score-a.score)}
function buildDraft(spec,baseId){const recommendations=recommendGameBases(spec),base=gameTemplates.find(t=>t.id===(baseId||recommendations[0]?.id))||gameTemplates[0];state.selectedTemplate=base.id;state.creationCustom=true;state.gameDraft={...spec,baseId:base.id,recommendations,title:(spec.season?spec.season+' ':'')+(spec.useCase?spec.useCase+' ':'')+base.type+' 초안'};state.settings={rewards:spec.labels.filter(n=>!/^꽝$|^미당첨$/.test(n)).map((name,i)=>({name,quantity:'',probability:+(100/spec.count).toFixed(2),delivery:'현장 수령'}))};state.consent=false;state.approved=false;state.published=false;state.paid=false;state.aiLayerDraft='';resetLayers();state.layers.find(l=>l.id==='logo').text='';state.layers.find(l=>l.id==='title').text=spec.season?spec.season+'의 행운을 만나보세요.':base.headline.replace(/<br>/g,'\n');state.layers.find(l=>l.id==='copy').text=spec.useCase?spec.useCase+'에서 룰렛을 돌리고 선물을 확인하세요.':'게임에 참여하고 선물을 확인하세요.';state.pageLayers['참여 시작'].find(l=>l.id==='logo').text='';state.pageLayers['결과'].find(l=>l.id==='logo').text='';state.toolTab='속성';state.layerId='game';}
function startGameDraft(spec,baseId){if(!state.eventName){retainEvent();state.gameDraftMode=true}else state.gameDraftMode=false;buildDraft(spec,baseId);state.editorTab='디자인';go(state.gameDraftMode?'game-draft':'editor')}
const gameDraftShell=shell;shell=function(body){return gameDraftShell(body).replace('>두잇킷</div>','>게임 초안</div>')};
const gameDraftSteps=steps;steps=function(active){if(state.gameDraftMode)return `<div class="draft-heading"><div><h1>게임 초안 편집</h1><p class="sub">${esc([state.gameDraft?.season,state.gameDraft?.useCase?state.gameDraft.useCase+'용':'',currentTemplate().type].filter(Boolean).join(' '))}</p></div></div>`;return gameDraftSteps(active)};
function draftSummary(){if(!state.gameDraft)return '';const d=state.gameDraft,base=gameTemplates.find(t=>t.id===d.baseId);return `<section class="draft-summary"><div><strong>${esc(base?.title||'선택한 템플릿')} 기반</strong><span>${esc(d.season||'기본 테마')} · ${esc(d.useCase||'이벤트')} · 보기 ${d.count}개</span></div><details><summary>추천 템플릿</summary><div class="draft-bases">${d.recommendations.slice(0,3).map(r=>{const t=gameTemplates.find(t=>t.id===r.id);return `<button data-draft-base="${r.id}" class="${r.id===d.baseId?'active':''}"><strong>${t.title}</strong><small>${r.reasons.join(' · ')}</small></button>`}).join('')}</div></details></section>`}
const templateDraftView=templates;templates=function(){let h=templateDraftView();h=h.replace('템플릿을 선택한 뒤 행사 정보를 입력합니다.','게임 조건을 입력하면 초안이 편집기로 열립니다.').replace('게임 아이디어를 입력하거나 아래 템플릿을 선택하세요.','자연어로 조건을 알려주세요. 맞는 템플릿을 바탕으로 게임 초안을 만듭니다.').replace(/placeholder="예: 성수 팝업[\s\S]*?">/,`placeholder="예: 박람회에서 가을에 진행할 룰렛을 만들고 싶어. 5개의 보기가 있고 선물은 가, 나, 다, 라, 꽝이 있어.">`);return h};
const draftCreate=createAction;createAction=function(a){if(a==='generate'){const p=document.getElementById('create-prompt').value.trim();if(!p)return toast('만들 게임의 조건을 입력해주세요.');state.createPrompt=p;startGameDraft(parseGamePrompt(p));return}draftCreate(a)};
const draftUse=useTemplate;useTemplate=function(id){const t=gameTemplates.find(t=>t.id===id);if(!state.eventName){state.gameDraftMode=true;const spec=parseGamePrompt(t.type+' 게임');startGameDraft(spec,id);if(t.draft){restoreGameSnapshot(t.draft);go('game-draft')}return}state.gameDraftMode=false;draftUse(id);if(t.draft){restoreGameSnapshot(t.draft);render()}};
const draftSketch=gameSketch;gameSketch=function(t){if(!state.gameDraft||t.kind!=='wheel'||t.id!==state.selectedTemplate)return draftSketch(t);const labels=state.gameDraft.labels,n=labels.length,colors=['var(--accent)',t.stage,'#ead4ac',t.paper],gradient=labels.map((_,i)=>`${colors[i%colors.length]} ${i*360/n}deg ${(i+1)*360/n}deg`).join(',');return `<div class="draft-wheel" style="background:conic-gradient(${gradient})" aria-label="${n}개 보기 룰렛">${labels.map((s,i)=>`<span style="--angle:${(i+.5)*360/n}deg">${esc(s)}</span>`).join('')}<b>GO</b></div>`};
const draftProps=properties;properties=function(){let h=draftProps();if(state.layerId==='game'&&state.gameDraft){h+=`<div class="field"><label for="draft-choice-count">보기 개수</label><input id="draft-choice-count" type="number" min="2" max="12" value="${state.gameDraft.count}"></div><div class="field"><label for="draft-choice-labels">보기 이름 · 한 줄에 하나</label><textarea id="draft-choice-labels">${esc(state.gameDraft.labels.join('\n'))}</textarea></div><p class="mini-label">${state.gameDraft.probabilityNote}</p>`}return h};
const draftEditor=editor;editor=function(prizes=false){let h=draftEditor(prizes);if(state.gameDraft)h=h.replace(editorSections(),draftSummary()+editorSections());if(state.gameDraftMode){h=h.replace(/<button class="btn" data-action="to-review">검토 요청<\/button>/g,'<button class="btn" data-draft="use-event">행사에 사용</button>').replace(/<button class="btn secondary" data-action="save">저장<\/button>/g,'<button class="btn secondary" data-draft="save">템플릿 저장</button>').replace(/<span class="mini-label">설정을 확인한 뒤 시안을 공유하세요.<\/span>/,'<span class="mini-label">행사 정보는 이 게임을 실제 행사에 사용할 때 입력합니다.</span>')}return h};
function gameSnapshot(){state.pageLayers[state.studioPage]=state.layers;return JSON.parse(JSON.stringify({gameDraft:state.gameDraft,layers:state.layers,pageLayers:state.pageLayers,settings:state.settings,selectedTemplate:state.selectedTemplate,studioPage:state.studioPage}))}
function restoreGameSnapshot(snapshot){Object.assign(state,JSON.parse(JSON.stringify(snapshot)));state.approved=false;state.consent=false;state.paid=false;state.published=false;state.layerId=state.layers.some(l=>l.id==='game')?'game':state.layers[0].id;state.layerHistory=[];state.editorTab='디자인'}
function updateDraftLabels(labels){const old=rewards();state.gameDraft.labels=labels;state.gameDraft.count=labels.length;state.settings.rewards=labels.filter(n=>!/^꽝$|^미당첨$/.test(n)).map(name=>({...old.find(p=>p.name===name),name,quantity:old.find(p=>p.name===name)?.quantity||'',probability:+(100/labels.length).toFixed(2),delivery:old.find(p=>p.name===name)?.delivery||'현장 수령'}));invalidateApproval()}
function draftAction(a){if(a==='save'){const snap=gameSnapshot(),base=currentTemplate(),id='saved-'+Date.now();const t={...base,id,title:state.gameDraft.title,brand:'MY TEMPLATE',desc:state.gameDraft.labels.join(' · '),draft:snap};state.savedGameTemplates.push(t);gameTemplates.push(t);try{localStorage.setItem('doitkit-game-templates',JSON.stringify(state.savedGameTemplates));toast('이 브라우저에 템플릿을 저장했습니다.')}catch(e){toast('현재 세션에 템플릿을 저장했습니다.')}return}if(a==='use-event'){state.attachGameDraft=gameSnapshot();state.gameDraftMode=false;state.pendingTemplate='';beginEvent();return}}
const attachSubmit=submitBasics;submitBasics=function(e){const snapshot=state.attachGameDraft;attachSubmit(e);if(snapshot&&route()!=='event-basic'){restoreGameSnapshot(snapshot);state.attachGameDraft=false;state.gameDraftMode=false;go('editor')}};
const clearDraftBegin=beginEvent;beginEvent=function(brand=''){state.gameDraftMode=false;clearDraftBegin(brand)};
const draftOpen=openWorkspaceEvent;openWorkspaceEvent=function(n){state.gameDraftMode=false;state.gameDraft=null;draftOpen(n)};
const draftRetain=retainEvent;retainEvent=function(){if(!state.gameDraftMode)draftRetain()};
const draftBind=bind;bind=function(){draftBind();app.querySelectorAll('[data-draft]').forEach(n=>n.onclick=()=>draftAction(n.dataset.draft));app.querySelectorAll('[data-draft-base]').forEach(n=>n.onclick=()=>{const spec={...state.gameDraft};buildDraft(spec,n.dataset.draftBase);render()});const labels=document.getElementById('draft-choice-labels');if(labels)labels.oninput=()=>{const rows=labels.value.split('\n').map(x=>x.trim()).filter(Boolean).slice(0,12);if(rows.length<2)return;updateDraftLabels(rows);document.getElementById('draft-choice-count').value=rows.length;document.getElementById('layer-canvas').innerHTML=layerCanvas();bindStudio()};const count=document.getElementById('draft-choice-count');if(count)count.onchange=()=>{let n=Math.max(2,Math.min(12,+count.value||2)),labels=state.gameDraft.labels.slice(0,n);while(labels.length<n)labels.push(' 선물 '+(labels.length+1));updateDraftLabels(labels);render()};const form=document.getElementById('basic-form');if(form)form.onsubmit=submitBasics;app.querySelectorAll('.sidebar a[href="#templates"]').forEach(n=>n.onclick=e=>{e.preventDefault();retainEvent();state.gameDraftMode=false;state.creationFlow=false;state.eventName='';state.gameDraft=null;state.createPrompt='';state.attachGameDraft=false;state.pendingTemplate='';go('templates')})};
const draftRender=render;render=function(){if(route()==='game-draft'){state.gameDraftMode=true;app.innerHTML=editor(false);document.body.dataset.screen='game-draft';document.title='게임 초안 · 두잇킷';bind()}else draftRender()};
screens.splice(screens.findIndex(s=>s[0]==='templates')+1,0,['game-draft','C-DRAFT','게임 초안 편집']);render();
const draftCrumbs=shell;shell=function(body){let h=draftCrumbs(body);if(state.gameDraftMode&&['game-draft','editor','prizes'].includes(route()))h=h.replace(/<div class="breadcrumbs">[\s\S]*?<\/div>/,`<div class="breadcrumbs"><a href="#templates">게임 템플릿</a><span>/</span><strong>게임 초안 편집</strong></div>`);return h};
const draftApprovalSignature=approvalSignature;approvalSignature=function(){return JSON.stringify({configuration:draftApprovalSignature(),choices:state.gameDraft?.labels||[]})};
const saveDraftContext=retainEvent;retainEvent=function(){saveDraftContext();if(!state.gameDraftMode&&state.eventName&&state.eventMemory[state.brandId+'|'+state.eventName])state.eventMemory[state.brandId+'|'+state.eventName].gameDraft=state.gameDraft?JSON.parse(JSON.stringify(state.gameDraft)):null};
const resumeDraftContext=openWorkspaceEvent;openWorkspaceEvent=function(n){resumeDraftContext(n);state.gameDraft=state.eventMemory[n.dataset.eventBrand+'|'+n.dataset.openEvent]?.gameDraft||null;render()};
const freshDraftBegin=beginEvent;beginEvent=function(brand=''){if(!state.attachGameDraft)state.gameDraft=null;freshDraftBegin(brand)};
